  for(const x of [-.95,.95]){box(busVisual,[.36,.24,.1],M.lamp,[x,1.12,-2.9],false);box(busVisual,[.34,.12,.08],M.white,[x,1.93,-2.9],false);}
  box(busVisual,[2.68,.16,.15],M.hub,[0,.34,-2.84]);
